const body = $json.body || {};
const phone = ((body.phone) || (body.customData && body.customData.phone) || '').toString();
return [{ json: {
  base_v2: 'https://api.pipedrive.com/api/v2',
  phone: phone,
  phone_digits: phone.replace(/[^0-9]/g, '').slice(-10)
}}];

const cfg = $('Search: Config').item.json;
const items = ($json.data && $json.data.items) ? $json.data.items : [];
const want = cfg.phone_digits;
let person_id = null;
for (const it of items) {
  const p = it.item || {};
  const phones = (p.phones || []).map(x => (x || '').toString().replace(/[^0-9]/g, '').slice(-10));
  if (!want || phones.includes(want) || items.length === 1) { person_id = p.id; break; }
}
return [{ json: { base_v2: cfg.base_v2, person_id: person_id } }];

const cfg = $('Search: Pick Person').item.json;
const deals = ($json.data && Array.isArray($json.data)) ? $json.data : [];
const deal_id = deals.length ? deals[0].id : null;
return [{ json: { person_id: cfg.person_id, deal_id: deal_id } }];

// ===== Base host (api_token routes to the right company; no subdomain needed) =====
const BASE_V2 = 'https://api.pipedrive.com/api/v2';
const BASE_V1 = 'https://api.pipedrive.com/v1';
// ===== Custom field keys (fill from dealFields discovery only if you use them) =====
const CF_DISPOSITION_KEY      = 'PUT_40CHAR_DISPOSITION_FIELD_KEY';
const CF_SECONDARY_STATUS_KEY = 'PUT_40CHAR_SECONDARY_FIELD_KEY';
const CALLBACK_LABEL_ID       = 0;
const PIPELINE_ID_DEFAULT     = 9;   // Online Leads /AI Stages (for create_deal)
// ===== Owner lookups (prefilled from /users discovery) =====
const OWNER_MAP = {"apps@kingsmencapital.ca": 31903733, "ammar@kingsmencapital.ca": 31856004, "asad@kingsmencapital.ca": 31874979, "azan@kingsmencapital.ca": 31874990, "colton@kingsmencapital.ca": 31902919, "harkirat@kingsmencapital.ca": 31874968, "jay@kingsmencapital.ca": 31874946, "jenn@kingsmencapital.ca": 31723234, "kevin.lecuyer@pipedrive.com": 14150914, "lilympour@kingsmencapital.ca": 31874935, "mayaa@kingsmencapital.ca": 31856015, "mohamed@kingsmencapital.ca": 31875001, "pamela@kingsmencapital.ca": 31874924, "tony.xavier@pipedrive.com": 13840680};
const OWNER_BY_NAME = {"admin": 31903733, "ammar sikandar": 31856004, "asad sikander": 31874979, "azan taj": 31874990, "colton vaughan": 31902919, "harkirat": 31874968, "jay rechtshaffen": 31874946, "jennifer belik": 31723234, "kevin lecuyer": 14150914, "leyli malayeri pour": 31874935, "mayaa swing": 31856015, "mohamed": 31875001, "pamela bouthillier": 31874924, "tony xavier": 13840680};

const body = $json.body || {};
const c = body.customData || body || {};
const num    = (v) => (v === undefined || v === null || v === '' || isNaN(Number(v))) ? null : Number(v);
const coerce = (v) => (v === undefined || v === null || v === '') ? null : (isNaN(Number(v)) ? v : Number(v));
const truthy = (v) => v === true || v === 'true' || v === 1 || v === '1';
const clean  = (s) => (s || '').toString().toLowerCase().replace(/[\u2010-\u2015]/g, '-').replace(/\s+/g, ' ').trim();

// Owner: explicit id > email > name (exact, then first-name fallback)
let owner_id = null;
if (c.owner_id) owner_id = num(c.owner_id);
if (owner_id == null) { const e = clean(c.owner_email); if (e && OWNER_MAP[e] !== undefined) owner_id = OWNER_MAP[e]; }
if (owner_id == null) {
  const nm = clean(c.owner_name);
  if (nm && OWNER_BY_NAME[nm] !== undefined) owner_id = OWNER_BY_NAME[nm];
  else if (nm) { for (const k in OWNER_BY_NAME) { if (k.split(' ')[0] === nm.split(' ')[0]) { owner_id = OWNER_BY_NAME[k]; break; } } }
}

return [{ json: {
  base_v2: BASE_V2,
  base_v1: BASE_V1,
  deal_id: c.deal_id || null,
  person_id: c.person_id || body.person_id || null,   // also accept top-level person_id
  stage_name: (c.stage_name || c.stage || '').toString(),
  stage_id: num(c.stage_id),                 // optional manual override
  status: c.status || null,
  lost_reason: c.lost_reason || null,
  add_label_id: num(c.add_label_id),
  remove_label_id: num(c.remove_label_id),
  callback_label_id: CALLBACK_LABEL_ID,
  remove_callback: truthy(c.remove_callback),
  note_html: c.note_html || null,
  owner_id: owner_id,
  owner_name_in: c.owner_name || null,
  cf_disposition_key: CF_DISPOSITION_KEY,
  cf_disposition_value: coerce(c.cf_disposition),
  cf_secondary_key: CF_SECONDARY_STATUS_KEY,
  secondary_status_value: coerce(c.secondary_status),
  create_deal: truthy(c.create_deal),
  deal_title: c.deal_title || (c.name ? (c.name + ' - SayVo') : 'SayVo Lead'),
  pipeline_id: num(c.pipeline_id) || PIPELINE_ID_DEFAULT,
  raw: c
}}];

const deal = ($json && $json.data) ? $json.data : {};
const existing = Array.isArray(deal.label_ids) ? deal.label_ids.map(Number) : [];
const norm = $('Disposition: Normalize').item.json;
const target = Number(norm.add_label_id);
const merged = Array.from(new Set([...existing, target]));
return [{ json: { base_v2: norm.base_v2, deal_id: norm.deal_id, label_ids: merged } }];

const deal = ($json && $json.data) ? $json.data : {};
const existing = Array.isArray(deal.label_ids) ? deal.label_ids.map(Number) : [];
const norm = $('Disposition: Normalize').item.json;
const target = Number(norm.remove_label_id);
const filtered = existing.filter(x => x !== target);
return [{ json: { base_v2: norm.base_v2, deal_id: norm.deal_id, label_ids: filtered.length ? filtered : null } }];

const deal = ($json && $json.data) ? $json.data : {};
const existing = Array.isArray(deal.label_ids) ? deal.label_ids.map(Number) : [];
const norm = $('Disposition: Normalize').item.json;
const target = Number(norm.callback_label_id);
const filtered = existing.filter(x => x !== target);
return [{ json: { base_v2: norm.base_v2, deal_id: norm.deal_id, label_ids: filtered.length ? filtered : null } }];

// Combines Pipedrive stages + active users + deal labels (tags) into one clean list.
const stagesResp = $('Discover: Stages').first().json;
const usersResp  = $('Discover: Owners').first().json;
const fieldsResp = $('Discover: Labels').first().json;
const stages = (stagesResp.data || []);
const users  = (usersResp.data || []);
const fields = (fieldsResp.data || []);
const labelField = fields.find(f => f.key === 'label');
const labels = (labelField && Array.isArray(labelField.options)) ? labelField.options : [];
const out = [];
for (const s of stages) out.push({ json: { kind:'STAGE', id:s.id, name:s.name, pipeline_id:s.pipeline_id, order:s.order_nr } });
for (const u of users) { if (u.active_flag === false) continue; out.push({ json: { kind:'OWNER', id:u.id, name:u.name, email:(u.email||'').toLowerCase() } }); }
for (const l of labels) out.push({ json: { kind:'LABEL', id:l.id, name:l.label } });  // id -> add_label_id
return out;

const clean = (s) => (s || '').toString().toLowerCase().replace(/[\u2018\u2019\u02bc']/g, '').replace(/[\u2010-\u2015-]/g, ' ').replace(/\s+/g, ' ').trim();
const cfg = $('Disposition: Normalize').item.json;
const src = ($('Get Deal (Stage)').item.json && $('Get Deal (Stage)').item.json.data) ? $('Get Deal (Stage)').item.json.data : {};
const person_id = src.person_id || cfg.person_id || null;
const title = src.title || (cfg.raw && cfg.raw.name) || 'AI Lead';
const listDeals = ($json && Array.isArray($json.data)) ? $json.data : [];
const name = clean(cfg.stage_name);

// Online Leads / AI Stages (pipeline 9): hyphens & spaces treated the same
const ONLINE_LEADS = {
  'kc website broker': 74, 'comparewise': 72, 'kc website client': 73, 'ai re engagement': 120,
  'qualified booked': 110, 'qualified didnt book': 111, 'unqualified': 112, 'not interested': 113,
  'busy': 114, 'ai voicemail': 115, 'voicemail': 116, 'wrong contact': 117, 'other': 118, 'ai other': 118, 'call failed': 119
};
const TERM_LOANS = {
  'qualified booked': 98, 'qualified didnt book': 97, 'not interested': 97, 'busy': 97
};

const byId = {};
if (src && src.id) byId[src.id] = src;
for (const dl of listDeals) { if (dl && dl.id) byId[dl.id] = dl; }
const deals = Object.values(byId);

const out = [];
let tlFound = false;
for (const dl of deals) {
  const pid = dl.pipeline_id;
  let sid = null;
  if (pid === 9)      { sid = (ONLINE_LEADS[name] !== undefined) ? ONLINE_LEADS[name] : null; }
  else if (pid === 2) { sid = (TERM_LOANS[name] !== undefined) ? TERM_LOANS[name] : null; tlFound = true; }
  if (sid != null) {
    out.push({ json: { action: 'update', base_v2: cfg.base_v2, deal_id: dl.id, stage_id: sid,
      owner_id: (pid === 2 && cfg.owner_id != null ? cfg.owner_id : null), pipeline_id: pid } });
  }
}
const tlTarget = (TERM_LOANS[name] !== undefined) ? TERM_LOANS[name] : null;
if (!tlFound && tlTarget != null && person_id) {
  out.push({ json: { action: 'create', base_v2: cfg.base_v2, person_id: person_id, pipeline_id: 2,
    stage_id: tlTarget, owner_id: (cfg.owner_id != null ? cfg.owner_id : null), title: title } });
}
return out;
